/**
 * roleAvatars — FibKing role-card image registry (web: WebP)
 *
 * Web uses compressed 512px WebP avatars generated by scripts/process_avatars.py.
 * See roleAvatars.ts for the native variant (raw PNG).
 */

import type { FibRole } from '@game-judge/game-engine/games/fibking/public';

import fibber from '../../../../assets/avatars/web/fibber.webp';
import guesser from '../../../../assets/avatars/web/guesser.webp';
import honest from '../../../../assets/avatars/web/honest.webp';

const FIBKING_ROLE_IMAGE_MAP: Record<FibRole, number> = {
  fibber,
  honest,
  guesser,
};

/** Resolve FibKing role IDs to the game's hand-drawn role-card assets. */
export function getRoleAvatar(roleId: FibRole): number {
  return FIBKING_ROLE_IMAGE_MAP[roleId];
}
